insert into public.questions (id, kind, prompt, options, marks, image_url) values ('22a92e40-54b6-520e-ab43-561091d6c3f3', 'short', 'Explain why the coloured liquid in a respirometer moves towards the organisms.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/The_respirometer_1.JPG?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('22a92e40-54b6-520e-ab43-561091d6c3f3', 'The organisms use O₂ in aerobic respiration [1]; the CO₂ they release is absorbed by soda lime/KOH [1]; so the volume of gas (and pressure) in the tube falls, drawing the liquid towards the organisms [1].', 'The organisms use O₂ in aerobic respiration [1]; the CO₂ they release is absorbed by soda lime/KOH [1]; so the volume of gas (and pressure) in the tube falls, drawing the liquid towards the organisms [1].', '[{"text": "Marking point 1", "any": ["o2 used", "take in oxygen", "uptake", "consume oxygen", "use o2", "uses o2", "use oxygen", "uses oxygen", "oxygen is used"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["soda lime", "koh"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["pressure", "volume decreases", "less gas", "volume falls"], "all": [], "marks": 1}]'::jsonb, 'The organisms use O₂ in aerobic respiration [1]; the CO₂ they release is absorbed by soda lime/KOH [1]; so the volume of gas (and pressure) in the tube falls, drawing the liquid towards the organisms [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('0a5fa622-3d29-5fc5-973f-fbb3018dc1e9', '22a92e40-54b6-520e-ab43-561091d6c3f3', 13);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('e75d4342-af1d-5273-ad6a-ab643d8bf54e', 'short', 'Explain why a sprinter''s muscles produce lactate in a 100 m race but not during a slow walk.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e75d4342-af1d-5273-ad6a-ab643d8bf54e', 'During sprinting, oxygen cannot be supplied to the muscles fast enough for aerobic respiration alone [1]; so muscles also respire anaerobically, producing lactate [1]; this releases ATP quickly without oxygen, although the yield per glucose is low [1]. During walking, oxygen supply meets demand, so respiration is aerobic.', 'During sprinting, oxygen cannot be supplied to the muscles fast enough for aerobic respiration alone [1]; so muscles also respire anaerobically, producing lactate [1]; this releases ATP quickly without oxygen, although the yield per glucose is low [1]. During walking, oxygen supply meets demand, so respiration is aerobic.', '[{"text": "Marking point 1", "any": ["insufficient oxygen", "not enough oxygen", "oxygen cannot", "lack of oxygen", "oxygen supply"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["anaerobic"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["fast", "quickly", "rapid", "extra atp", "more atp"], "all": [], "marks": 1}]'::jsonb, 'During sprinting, oxygen cannot be supplied to the muscles fast enough for aerobic respiration alone [1]; so muscles also respire anaerobically, producing lactate [1]; this releases ATP quickly without oxygen, although the yield per glucose is low [1]. During walking, oxygen supply meets demand, so respiration is aerobic.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('0a5fa622-3d29-5fc5-973f-fbb3018dc1e9', 'e75d4342-af1d-5273-ad6a-ab643d8bf54e', 14);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('aeffd40e-c3c3-5af8-9d50-0bdbea20421b', 'short', 'Explain why removing hydrogen from a substrate is an oxidation.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('aeffd40e-c3c3-5af8-9d50-0bdbea20421b', 'Each hydrogen atom removed takes an electron with it [1]; oxidation is the loss of electrons, so dehydrogenation oxidises the substrate [1].', 'Each hydrogen atom removed takes an electron with it [1]; oxidation is the loss of electrons, so dehydrogenation oxidises the substrate [1].', '[{"text": "Marking point 1", "any": ["electron"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["loss", "lose", "removed", "removal"], "all": [], "marks": 1}]'::jsonb, 'Each hydrogen atom removed takes an electron with it [1]; oxidation is the loss of electrons, so dehydrogenation oxidises the substrate [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
