insert into public.questions (id, kind, prompt, options, marks, image_url) values ('083b2d69-0161-5797-b3f8-177e0f8920e5', 'short', 'Explain why converting pyruvate to lactate allows glycolysis to continue in anaerobic conditions.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('083b2d69-0161-5797-b3f8-177e0f8920e5', 'Glycolysis needs NAD to accept hydrogen in its oxidation step [1]; in anaerobic conditions pyruvate accepts the hydrogen from reduced NAD, forming lactate [1]; this regenerates (oxidises) NAD so glycolysis can continue producing 2 ATP per glucose [1].', 'Glycolysis needs NAD to accept hydrogen in its oxidation step [1]; in anaerobic conditions pyruvate accepts the hydrogen from reduced NAD, forming lactate [1]; this regenerates (oxidises) NAD so glycolysis can continue producing 2 ATP per glucose [1].', '[{"text": "Marking point 1", "any": ["regenerate", "nad is regenerated", "nad is reformed"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["accepts hydrogen", "hydrogen to pyruvate"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["glycolysis needs nad", "oxidation step", "nad is required"], "all": [], "marks": 1}]'::jsonb, 'Glycolysis needs NAD to accept hydrogen in its oxidation step [1]; in anaerobic conditions pyruvate accepts the hydrogen from reduced NAD, forming lactate [1]; this regenerates (oxidises) NAD so glycolysis can continue producing 2 ATP per glucose [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
