insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('771da326-e7d5-5187-a6b8-d7012dcdc451', 'Both use glycolysis to produce pyruvate and a net 2 ATP, regenerating NAD [1]; humans convert pyruvate to lactate, while yeast converts it to ethanol [1]; yeast also releases CO₂, humans do not [1].', 'Both use glycolysis to produce pyruvate and a net 2 ATP, regenerating NAD [1]; humans convert pyruvate to lactate, while yeast converts it to ethanol [1]; yeast also releases CO₂, humans do not [1].', '[{"text": "Marking point 1", "any": ["glycolysis", "same pathway"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["ethanol"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["co2"], "all": [], "marks": 1}]'::jsonb, 'Both use glycolysis to produce pyruvate and a net 2 ATP, regenerating NAD [1]; humans convert pyruvate to lactate, while yeast converts it to ethanol [1]; yeast also releases CO₂, humans do not [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
