insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('444feda2-174b-5ab7-a9ce-a0e944867a40', 'Pyruvate is decarboxylated, releasing CO₂ [1]; it is oxidised, with hydrogen accepted by NAD to form reduced NAD [1]; the remaining acetyl group is attached to coenzyme A (acetyl-CoA), which carries it into the Krebs cycle [1].', 'Pyruvate is decarboxylated, releasing CO₂ [1]; it is oxidised, with hydrogen accepted by NAD to form reduced NAD [1]; the remaining acetyl group is attached to coenzyme A (acetyl-CoA), which carries it into the Krebs cycle [1].', '[{"text": "Marking point 1", "any": ["decarboxyl", "carbon dioxide", "co2"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["oxidised", "oxidation", "reduced nad", "nad", "hydrogen removed"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["acetyl", "coenzyme a", "coa"], "all": [], "marks": 1}]'::jsonb, 'Pyruvate is decarboxylated, releasing CO₂ [1]; it is oxidised, with hydrogen accepted by NAD to form reduced NAD [1]; the remaining acetyl group is attached to coenzyme A (acetyl-CoA), which carries it into the Krebs cycle [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
