insert into public.questions (id, kind, prompt, options, marks, image_url) values ('3a68b2c3-0ba2-5ef8-bdb9-cc114bc8f2ed', 'short', 'Distinguish between cell respiration and gas exchange.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mitochondrion_structure.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('3a68b2c3-0ba2-5ef8-bdb9-cc114bc8f2ed', 'Cell respiration is a set of chemical reactions inside cells that release energy and make ATP [1]; gas exchange is the diffusion of O₂ and CO₂ across an exchange surface such as the alveoli [1].', 'Cell respiration is a set of chemical reactions inside cells that release energy and make ATP [1]; gas exchange is the diffusion of O₂ and CO₂ across an exchange surface such as the alveoli [1].', '[{"text": "Marking point 1", "any": ["chemical", "inside cells", "atp", "release energy"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["diffusion", "surface", "across"], "all": [], "marks": 1}]'::jsonb, 'Cell respiration is a set of chemical reactions inside cells that release energy and make ATP [1]; gas exchange is the diffusion of O₂ and CO₂ across an exchange surface such as the alveoli [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
