insert into public.questions (id, kind, prompt, options, marks, image_url) values ('22a92e40-54b6-520e-ab43-561091d6c3f3', 'short', 'Explain why the coloured liquid in a respirometer moves towards the organisms.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/The_respirometer_1.JPG?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('22a92e40-54b6-520e-ab43-561091d6c3f3', 'The organisms use O₂ in aerobic respiration [1]; the CO₂ they release is absorbed by soda lime/KOH [1]; so the volume of gas (and pressure) in the tube falls, drawing the liquid towards the organisms [1].', 'The organisms use O₂ in aerobic respiration [1]; the CO₂ they release is absorbed by soda lime/KOH [1]; so the volume of gas (and pressure) in the tube falls, drawing the liquid towards the organisms [1].', '[{"text": "Marking point 1", "any": ["o2 used", "take in oxygen", "uptake", "consume oxygen", "use o2", "uses o2", "use oxygen", "uses oxygen", "oxygen is used"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["soda lime", "koh"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["pressure", "volume decreases", "less gas", "volume falls"], "all": [], "marks": 1}]'::jsonb, 'The organisms use O₂ in aerobic respiration [1]; the CO₂ they release is absorbed by soda lime/KOH [1]; so the volume of gas (and pressure) in the tube falls, drawing the liquid towards the organisms [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
