insert into public.questions (id, kind, prompt, options, marks, image_url) values ('2042f8e8-64bd-54eb-8869-5ab02761c1dc', 'short', 'Explain how air is drawn into the lungs.', '[]'::jsonb, 4, 'https://commons.wikimedia.org/wiki/Special:FilePath/Alveolus_diagram.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('2042f8e8-64bd-54eb-8869-5ab02761c1dc', 'The diaphragm contracts and flattens [1]; external intercostal muscles contract, moving the ribs up and out [1]; the volume of the thorax increases [1]; so pressure inside falls below atmospheric pressure and air flows in [1].', 'The diaphragm contracts and flattens [1]; external intercostal muscles contract, moving the ribs up and out [1]; the volume of the thorax increases [1]; so pressure inside falls below atmospheric pressure and air flows in [1].', '[{"text": "Marking point 1", "any": ["diaphragm contracts", "diaphragm flattens"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["external intercostal", "ribs up"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["volume increases", "thorax gets bigger"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["pressure decreases", "lower pressure", "pressure drops", "below atmospheric"], "all": [], "marks": 1}]'::jsonb, 'The diaphragm contracts and flattens [1]; external intercostal muscles contract, moving the ribs up and out [1]; the volume of the thorax increases [1]; so pressure inside falls below atmospheric pressure and air flows in [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
