insert into public.questions (id, kind, prompt, options, marks, image_url) values ('db2cd421-9a53-5023-bb00-8171f4da946a', 'short', 'Suggest why tidal volume increases during exercise.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lungvolumes.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('db2cd421-9a53-5023-bb00-8171f4da946a', 'Muscles respire faster during exercise and need more O₂ [1]; more CO₂ is produced and must be removed, so deeper breaths increase gas exchange [1].', 'Muscles respire faster during exercise and need more O₂ [1]; more CO₂ is produced and must be removed, so deeper breaths increase gas exchange [1].', '[{"text": "Marking point 1", "any": ["respiration", "more oxygen", "oxygen demand", "need more oxygen", "respire", "more o2", "need more"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["carbon dioxide", "co2", "remove"], "all": [], "marks": 1}]'::jsonb, 'Muscles respire faster during exercise and need more O₂ [1]; more CO₂ is produced and must be removed, so deeper breaths increase gas exchange [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('6ada932e-33a7-5830-9fbf-fe505e0541a7', 'db2cd421-9a53-5023-bb00-8171f4da946a', 15);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('8113dc36-9253-5f6d-917d-d80876997102', 'short', 'Describe how the structure of the lungs is adapted for gas exchange.', '[]'::jsonb, 4, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('8113dc36-9253-5f6d-917d-d80876997102', 'Millions of alveoli give a very large surface area [1]; alveolar and capillary walls are thin (one cell), so the diffusion distance is short [1]; dense capillary networks maintain the gradient [1]; surfactant keeps alveoli open and moist / branched bronchioles distribute air to all alveoli [1].', 'Millions of alveoli give a very large surface area [1]; alveolar and capillary walls are thin (one cell), so the diffusion distance is short [1]; dense capillary networks maintain the gradient [1]; surfactant keeps alveoli open and moist / branched bronchioles distribute air to all alveoli [1].', '[{"text": "Marking point 1", "any": ["large surface area", "many alveoli", "high surface area"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["thin", "one cell", "short diffusion"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["capillar", "blood supply"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["surfactant", "moist", "bronchiole"], "all": [], "marks": 1}]'::jsonb, 'Millions of alveoli give a very large surface area [1]; alveolar and capillary walls are thin (one cell), so the diffusion distance is short [1]; dense capillary networks maintain the gradient [1]; surfactant keeps alveoli open and moist / branched bronchioles distribute air to all alveoli [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('6ada932e-33a7-5830-9fbf-fe505e0541a7', '8113dc36-9253-5f6d-917d-d80876997102', 16);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('c05d4482-935a-5d9d-b8e8-5c4e20c8c7d0', 'mcq', 'Match each leaf structure to its role.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('c05d4482-935a-5d9d-b8e8-5c4e20c8c7d0', 1, 'Cuticle: reduces water loss. Guard cells: open/close stomata. Spongy mesophyll: gas exchange surface. Xylem: water in. Phloem: sugars out.', 'Guard cells') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('6ada932e-33a7-5830-9fbf-fe505e0541a7', 'c05d4482-935a-5d9d-b8e8-5c4e20c8c7d0', 17);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('0f4ebdae-9794-50c0-8299-e90956bb005b', 'short', 'Explain why transpiration is described as a consequence of gas exchange.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('0f4ebdae-9794-50c0-8299-e90956bb005b', 'Stomata must open to let CO₂ in for photosynthesis [1]; when they are open, water vapour diffuses out from the moist air spaces, so water loss is unavoidable [1].', 'Stomata must open to let CO₂ in for photosynthesis [1]; when they are open, water vapour diffuses out from the moist air spaces, so water loss is unavoidable [1].', '[{"text": "Marking point 1", "any": ["stomata open", "open stomata"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["carbon dioxide", "co2", "photosynthesis"], "all": [], "marks": 1}]'::jsonb, 'Stomata must open to let CO₂ in for photosynthesis [1]; when they are open, water vapour diffuses out from the moist air spaces, so water loss is unavoidable [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('6ada932e-33a7-5830-9fbf-fe505e0541a7', '0f4ebdae-9794-50c0-8299-e90956bb005b', 18);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('db66700b-4a32-5fac-b53e-74b47f339743', 'short', 'Explain why stomatal density should be counted in several fields of view.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('db66700b-4a32-5fac-b53e-74b47f339743', 'Stomata are not evenly spread, so counts vary between fields of view [1]; a mean of several counts is more reliable / representative of the leaf [1].', 'Stomata are not evenly spread, so counts vary between fields of view [1]; a mean of several counts is more reliable / representative of the leaf [1].', '[{"text": "Marking point 1", "any": ["vari", "differ", "not the same", "vary", "not evenly", "uneven"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["reliab", "mean", "average", "representative"], "all": [], "marks": 1}]'::jsonb, 'Stomata are not evenly spread, so counts vary between fields of view [1]; a mean of several counts is more reliable / representative of the leaf [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('6ada932e-33a7-5830-9fbf-fe505e0541a7', 'db66700b-4a32-5fac-b53e-74b47f339743', 19);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('1792a300-6530-5c0d-81db-a04018978709', 'short', 'Suggest two leaf adaptations that reduce water loss in dry habitats, with reasons.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('1792a300-6530-5c0d-81db-a04018978709', 'Thick waxy cuticle reduces evaporation from the surface [1]; fewer or sunken stomata / hairs / rolled leaves trap humid air and reduce the water vapour gradient [1].', 'Thick waxy cuticle reduces evaporation from the surface [1]; fewer or sunken stomata / hairs / rolled leaves trap humid air and reduce the water vapour gradient [1].', '[{"text": "Marking point 1", "any": ["cuticle", "wax"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["fewer stomata", "sunken", "hairs", "rolled", "small leaves", "spines"], "all": [], "marks": 1}]'::jsonb, 'Thick waxy cuticle reduces evaporation from the surface [1]; fewer or sunken stomata / hairs / rolled leaves trap humid air and reduce the water vapour gradient [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('6ada932e-33a7-5830-9fbf-fe505e0541a7', '1792a300-6530-5c0d-81db-a04018978709', 20);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a3eb8f28-9e2d-5ad1-aca1-d2c3e2085cea', 'short', 'Explain the S-shape of the oxygen dissociation curve of haemoglobin.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Oxygen-Haemoglobin_dissociation_curves.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('a3eb8f28-9e2d-5ad1-aca1-d2c3e2085cea', 'At low pO₂ the first O₂ binds with difficulty, so the curve starts shallow [1]; binding changes the shape of haemoglobin, so further O₂ binds more easily (cooperative binding), giving the steep middle [1]; at high pO₂ all four haem groups are occupied, so the curve levels off [1].', 'At low pO₂ the first O₂ binds with difficulty, so the curve starts shallow [1]; binding changes the shape of haemoglobin, so further O₂ binds more easily (cooperative binding), giving the steep middle [1]; at high pO₂ all four haem groups are occupied, so the curve levels off [1].', '[{"text": "Marking point 1", "any": ["first oxygen", "low affinity at low", "hard to bind"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["shape change", "cooperative", "conformation", "easier"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["plateau", "saturated", "all sites", "four"], "all": [], "marks": 1}]'::jsonb, 'At low pO₂ the first O₂ binds with difficulty, so the curve starts shallow [1]; binding changes the shape of haemoglobin, so further O₂ binds more easily (cooperative binding), giving the steep middle [1]; at high pO₂ all four haem groups are occupied, so the curve levels off [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('6ada932e-33a7-5830-9fbf-fe505e0541a7', 'a3eb8f28-9e2d-5ad1-aca1-d2c3e2085cea', 21);
