insert into public.questions (id, kind, prompt, options, marks, image_url) values ('5938933e-7cc9-5a04-9be1-3a907e6bb87b', 'mcq', 'Foetal or adult haemoglobin?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('5938933e-7cc9-5a04-9be1-3a907e6bb87b', 0, 'Higher affinity, loads in placenta: foetal. Curve to the right, unloads in placenta: adult.', 'Foetal') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('6ada932e-33a7-5830-9fbf-fe505e0541a7', '5938933e-7cc9-5a04-9be1-3a907e6bb87b', 26);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('e4df402e-91cf-54a4-bc93-bfec0b62d7bb', 'short', 'Explain the advantage to the foetus of having haemoglobin with a higher affinity for oxygen.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e4df402e-91cf-54a4-bc93-bfec0b62d7bb', 'At the low pO₂ in the placenta, foetal haemoglobin is more saturated than maternal haemoglobin [1]; so oxygen is transferred from the mother''s blood to the foetus''s blood [1].', 'At the low pO₂ in the placenta, foetal haemoglobin is more saturated than maternal haemoglobin [1]; so oxygen is transferred from the mother''s blood to the foetus''s blood [1].', '[{"text": "Marking point 1", "any": ["more saturated", "higher saturation", "binds more", "takes oxygen", "same partial pressure"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["mother", "maternal", "placenta"], "all": [], "marks": 1}]'::jsonb, 'At the low pO₂ in the placenta, foetal haemoglobin is more saturated than maternal haemoglobin [1]; so oxygen is transferred from the mother''s blood to the foetus''s blood [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
