insert into public.questions (id, kind, prompt, options, marks, image_url) values ('d6235a97-a93e-54f1-b189-38c72c262246', 'short', 'Explain how the structure of arteries helps them maintain high blood pressure.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/2102_Comparison_of_Artery_and_Vein.jpg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('d6235a97-a93e-54f1-b189-38c72c262246', 'Elastic fibres stretch when blood is pumped in at high pressure [1] and recoil between heartbeats, pushing blood on and maintaining pressure [1]; a thick layer of smooth muscle (and collagen) makes the wall strong enough to withstand the pressure [1].', 'Elastic fibres stretch when blood is pumped in at high pressure [1] and recoil between heartbeats, pushing blood on and maintaining pressure [1]; a thick layer of smooth muscle (and collagen) makes the wall strong enough to withstand the pressure [1].', '[{"text": "Marking point 1", "any": ["elastic"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["recoil", "stretches"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["muscle", "thick"], "all": [], "marks": 1}]'::jsonb, 'Elastic fibres stretch when blood is pumped in at high pressure [1] and recoil between heartbeats, pushing blood on and maintaining pressure [1]; a thick layer of smooth muscle (and collagen) makes the wall strong enough to withstand the pressure [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
