insert into public.questions (id, kind, prompt, options, marks, image_url) values ('529bac25-0c9a-568e-8c08-798190059217', 'short', 'Explain how blood is returned to the heart in veins despite low pressure.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/2102_Comparison_of_Artery_and_Vein.jpg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
