insert into public.questions (id, kind, prompt, options, marks, image_url) values ('376c27b3-3755-5142-9389-05bf9ffcd6bf', 'short', 'Distinguish between the structure of arteries and veins.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('376c27b3-3755-5142-9389-05bf9ffcd6bf', 'Arteries have thicker walls than veins [1]; arteries have a narrow lumen, veins a wide lumen [1]; veins have valves, arteries do not (except at the heart) [1]; arteries have more elastic fibres and smooth muscle [1]. (Any three.)', 'Arteries have thicker walls than veins [1]; arteries have a narrow lumen, veins a wide lumen [1]; veins have valves, arteries do not (except at the heart) [1]; arteries have more elastic fibres and smooth muscle [1]. (Any three.)', '[{"text": "Marking point 1", "any": ["thicker wall", "thinner wall"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["lumen", "wider lumen"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["valve"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["elastic", "muscle"], "all": [], "marks": 1}]'::jsonb, 'Arteries have thicker walls than veins [1]; arteries have a narrow lumen, veins a wide lumen [1]; veins have valves, arteries do not (except at the heart) [1]; arteries have more elastic fibres and smooth muscle [1]. (Any three.)') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
