insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('5c4cdcd2-35eb-5a9a-9ef9-8eb851aab9a5', 'Water in xylem is under tension (negative pressure) [1]; lignin strengthens the walls so the vessels do not collapse inward [1].', 'Water in xylem is under tension (negative pressure) [1]; lignin strengthens the walls so the vessels do not collapse inward [1].', '[{"text": "Marking point 1", "any": ["tension", "negative pressure", "pulled"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["collapse", "inward", "strength", "support"], "all": [], "marks": 1}]'::jsonb, 'Water in xylem is under tension (negative pressure) [1]; lignin strengthens the walls so the vessels do not collapse inward [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
