insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('763472ef-3b9b-52d5-840b-6be728f3ce9f', 'Sieve plates with pores let sap flow between elements [1]; no nucleus and reduced cytoplasm leave space for flow [1]; companion cells have many mitochondria providing ATP to load sucrose actively, passing it through plasmodesmata [1].', 'Sieve plates with pores let sap flow between elements [1]; no nucleus and reduced cytoplasm leave space for flow [1]; companion cells have many mitochondria providing ATP to load sucrose actively, passing it through plasmodesmata [1].', '[{"text": "Marking point 1", "any": ["sieve plate", "pores"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["no nucleus", "few organelles", "reduced cytoplasm"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["mitochondria", "atp", "load"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["plasmodesmata"], "all": [], "marks": 1}]'::jsonb, 'Sieve plates with pores let sap flow between elements [1]; no nucleus and reduced cytoplasm leave space for flow [1]; companion cells have many mitochondria providing ATP to load sucrose actively, passing it through plasmodesmata [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
